export function encodeCursor(index) {
  return Buffer.from(`idx:${index}`, 'utf8').toString('base64url');
}

export function decodeCursor(cursor) {
  const raw = Buffer.from(cursor, 'base64url').toString('utf8');
  if (!raw.startsWith('idx:')) throw new Error(`malformed cursor: ${cursor}`);
  const index = Number(raw.slice(4));
  if (!Number.isInteger(index) || index < 0) throw new Error(`malformed cursor: ${cursor}`);
  return index;
}

export function paginate(items, options = {}) {
  const limit = options.limit ?? 3;
  if (!Number.isInteger(limit) || limit < 1) throw new Error(`limit must be a positive integer, got ${limit}`);
  const start = options.cursor == null ? 0 : decodeCursor(options.cursor) + 1;
  const page = items.slice(start, start + limit);
  const nextIndex = start + page.length;
  const nextCursor = nextIndex < items.length ? encodeCursor(nextIndex) : null;
  return { items: page, nextCursor };
}

import { paginate } from './lib/paginate.mjs';

const ITEMS = Array.from({ length: 10 }, (_, i) => ({ id: `item-${i + 1}` }));

function walk(limit) {
  const seen = [];
  let cursor = null;
  for (let hops = 0; hops < 10; hops += 1) {
    const page = paginate(ITEMS, { limit, cursor });
    seen.push(...page.items.map((item) => item.id));
    cursor = page.nextCursor;
    if (!cursor) break;
  }
  return seen;
}

const expected = ITEMS.map((item) => item.id);
const got = walk(3);
if (JSON.stringify(got) !== JSON.stringify(expected)) {
  console.log(`CASE boundary: expected ${JSON.stringify(expected)} got ${JSON.stringify(got)}`);
  process.exit(1);
}
